"use strict";(self.webpackChunkgolden_forest_website=self.webpackChunkgolden_forest_website||[]).push([["64117"],{43058(e){e.exports=JSON.parse('{"tag":{"label":"security","permalink":"/pr-preview/pr-338/docs/tags/security","allTagsPath":"/pr-preview/pr-338/docs/tags","count":29,"items":[{"id":"Security/debian-ubuntu-hardening","title":"Advanced Debian/Ubuntu Hardening Strategy (2026)","description":"Comprehensive guide to securing Debian and Ubuntu servers with SSH hardening, 2FA/MFA, kernel sysctl tuning, file integrity monitoring, rootkit detection, and automated security updates.","permalink":"/pr-preview/pr-338/docs/Security/debian-ubuntu-hardening"},{"id":"Security/agent-security","title":"Agent Security","description":"Practical, tool-agnostic guide to preventing AI agents from leaking secrets \u2014 covering OpenCode modes, permissions, sandboxing, and architectural defenses.","permalink":"/pr-preview/pr-338/docs/Security/agent-security"},{"id":"Develop-Code/AI-Development/Skills/cloudflare-security-audit-skill","title":"Cloudflare Security Audit Skill","description":"Cloudflare\'s open-source coding-agent skill that runs multi-phase security audits with independently verified, machine-readable findings.","permalink":"/pr-preview/pr-338/docs/Develop-Code/AI-Development/Skills/cloudflare-security-audit-skill"},{"id":"Develop-Code/AI-Development/MCPs/cve-mcp-server","title":"CVE MCP Server","description":"27 security intelligence tools across 21 APIs \u2014 CVE lookup, EPSS scoring, CISA KEV, MITRE ATT&CK, Shodan, VirusTotal, and more \u2014 all accessible through Claude via the Model Context Protocol.","permalink":"/pr-preview/pr-338/docs/Develop-Code/AI-Development/MCPs/cve-mcp-server"},{"id":"Develop-Code/AI-Development/Skills/cybersecurity-skills","title":"Cybersecurity Skills","description":"734+ structured cybersecurity skills for AI agents, following the agentskills.io standard","permalink":"/pr-preview/pr-338/docs/Develop-Code/AI-Development/Skills/cybersecurity-skills"},{"id":"OS-and-Hardware/OS/GNU-Linux/Hardware/Tuning/disable-cpu-mitigations","title":"Disable mitigations","description":"There is anumber of kernel boot parameters available to disable or fine-tune hardware vulnerability mitigations:","permalink":"/pr-preview/pr-338/docs/OS-and-Hardware/OS/GNU-Linux/Hardware/Tuning/disable-cpu-mitigations"},{"id":"OS-and-Hardware/OS/GNU-Linux/dropbear","title":"Dropbear","description":"Install","permalink":"/pr-preview/pr-338/docs/OS-and-Hardware/OS/GNU-Linux/dropbear"},{"id":"Security/gh-secure","title":"gh-secure","description":"Official GitHub CLI extension from the GitHub Security Lab that enables branch protection, private vulnerability reporting, secret scanning, Dependabot, and CodeQL on a repository in about 2 minutes.","permalink":"/pr-preview/pr-338/docs/Security/gh-secure"},{"id":"Infrastructure-and-Cloud/DevOps/CI/SecurityChecks/guardrails","title":"GuardRails","description":"A SaaS which runs on Amazon Web Services, the company also offers a version for on-premise deployments. The platform is offered free of charge for anyone who wants to focus only on public code repositories. Paid versions start at $39 monthly for startups.","permalink":"/pr-preview/pr-338/docs/Infrastructure-and-Cloud/DevOps/CI/SecurityChecks/guardrails"},{"id":"Develop-Code/QA/inspec","title":"Inspec.io","description":"Chef Inspec provides a language for describing security and compliance rules that can be shared between software engineers, operations, and security engineers.","permalink":"/pr-preview/pr-338/docs/Develop-Code/QA/inspec"},{"id":"Infrastructure-and-Cloud/Cloud-Platform/Kubernetes/k8s-hardening","title":"K8s hardening","description":"Guides","permalink":"/pr-preview/pr-338/docs/Infrastructure-and-Cloud/Cloud-Platform/Kubernetes/k8s-hardening"},{"id":"Infrastructure-and-Cloud/Cloud-Platform/Kubernetes/Concepts/k8s-secrets","title":"K8s Secrets","description":"A Secret is an object that contains a small amount of sensitive data such as a password, a token, or a key. Such information might otherwise be put in a Pod specification or in a container image. Using a Secret means that you don\'t need to include confidential data in your application code.","permalink":"/pr-preview/pr-338/docs/Infrastructure-and-Cloud/Cloud-Platform/Kubernetes/Concepts/k8s-secrets"},{"id":"Apps-and-utilities/Certificates/lets-encrypt","title":"Let\'s Encrypt","description":"Let\u2019s Encrypt is a free, automated, and open certificate authority (CA), run for the public\u2019s benefit. It is a service provided by the Internet Security Research Group (ISRG).","permalink":"/pr-preview/pr-338/docs/Apps-and-utilities/Certificates/lets-encrypt"},{"id":"OS-and-Hardware/OS/GNU-Linux/Kernel/linux-secureboot","title":"Linux Secure Boot","description":"Is a safe boot mode for UEFI that blocks execution of no certified software in your system boot.","permalink":"/pr-preview/pr-338/docs/OS-and-Hardware/OS/GNU-Linux/Kernel/linux-secureboot"},{"id":"Apps-and-utilities/Networking/mitmproxy","title":"mitmproxy","description":"A free and open-source interactive HTTPS proxy for intercepting, inspecting, modifying, and replaying HTTP/HTTPS traffic across CLI, web, and Python API interfaces.","permalink":"/pr-preview/pr-338/docs/Apps-and-utilities/Networking/mitmproxy"},{"id":"Security/nmap-unleashed","title":"nmapUnleashed (nu) - Modern Nmap Wrapper","description":"nmapUnleashed (nu) is a modern CLI wrapper for Nmap, designed to make network scanning more comfortable and effective. It provides all familiar Nmap commands with extended features such as multithreading, easy scan management, and improved overview.","permalink":"/pr-preview/pr-338/docs/Security/nmap-unleashed"},{"id":"Security/npm-libs","title":"npm Supply Chain Attacks - Protecting Your Projects","description":"How the May 2026 TanStack npm compromise happened and how to protect your projects from lifecycle script injection attacks.","permalink":"/pr-preview/pr-338/docs/Security/npm-libs"},{"id":"Security/opensandbox","title":"OpenSandbox - Secure Agent Infrastructure by Alibaba","description":"Alibaba just handed the AI agent community a production-grade sandbox for free. OpenSandbox is a full-stack platform for running untrusted agent code safely \u2014 and it\'s open source.","permalink":"/pr-preview/pr-338/docs/Security/opensandbox"},{"id":"Security/owasp","title":"OWASP","description":"Open Web Application Security Project - Top 10, Cheat Sheet Series, ASVS, and Proactive Controls for building and verifying secure applications.","permalink":"/pr-preview/pr-338/docs/Security/owasp"},{"id":"Security/privacy-guide","title":"Privacy Guides","description":"Independent, non-profit resource for privacy and security tool recommendations and best practices.","permalink":"/pr-preview/pr-338/docs/Security/privacy-guide"},{"id":"Apps-and-utilities/secrets-management-tools","title":"Secrets Management Tools","description":"A comprehensive guide to industry-standard secrets management solutions including HashiCorp Vault, AWS Secrets Manager, SOPS, and Teller (by TellerOps).","permalink":"/pr-preview/pr-338/docs/Apps-and-utilities/secrets-management-tools"},{"id":"Infrastructure-and-Cloud/DevOps/CI/SecurityChecks/securing-tools","title":"Securing Tools","description":"Articles","permalink":"/pr-preview/pr-338/docs/Infrastructure-and-Cloud/DevOps/CI/SecurityChecks/securing-tools"},{"id":"Security/index","title":"Security \u{1F6E1}\uFE0F","description":"Notes related to protecting systems and ensuring the functional quality of software.","permalink":"/pr-preview/pr-338/docs/Security/"},{"id":"Security/sniffnet","title":"Sniffnet","description":"A cross-platform, Rust-based network traffic monitor with real-time visualization, geolocation, and protocol detection.","permalink":"/pr-preview/pr-338/docs/Security/sniffnet"},{"id":"Infrastructure-and-Cloud/DevOps/CI/SecurityChecks/sonarqube","title":"SonarQube","description":"SonarQube is a web-based software analysis platform with open source roots that can go a long way to delivering cleaner, issue-free code.","permalink":"/pr-preview/pr-338/docs/Infrastructure-and-Cloud/DevOps/CI/SecurityChecks/sonarqube"},{"id":"OS-and-Hardware/OS/GNU-Linux/ssh","title":"ssh client","description":"Tunnel","permalink":"/pr-preview/pr-338/docs/OS-and-Hardware/OS/GNU-Linux/ssh"},{"id":"Security/emudhra-ca-breach","title":"The eMudhra Intermediate CA Compromise","description":"Eight eMudhra intermediate CA private keys were recoverable from the certificates themselves. How to check and fix macOS and Linux trust stores.","permalink":"/pr-preview/pr-338/docs/Security/emudhra-ca-breach"},{"id":"Develop-Code/AI-Development/Workflows/vercel-ai-workflow","title":"Vercel CEO AI Workflow","description":"Vercel\'s CEO builds with agents by testing ideas as MVPs, checking drift against a spec, and running breaker and first-time-user agents before shipping.","permalink":"/pr-preview/pr-338/docs/Develop-Code/AI-Development/Workflows/vercel-ai-workflow"},{"id":"Infrastructure-and-Cloud/Networking/VPN/wireguard-vpn","title":"WireGuard VPN","description":"WireGuard\xae is an extremely simple yet fast and modern VPN that utilizes state-of-the-art cryptography.","permalink":"/pr-preview/pr-338/docs/Infrastructure-and-Cloud/Networking/VPN/wireguard-vpn"}],"unlisted":false}}')}}]);